+/// Persist complete ingestion data before publishing its restart marker. The
+/// final ordinary directory flush makes the rename visible after process exit;
+/// on Apple it may still be lost on power failure until a later full sync.
+/// Both the old and new catalog must therefore remain recoverable. Callers must
+/// harden this publication before WAL writes, reorgs or destructive maintenance.
+pub(crate) fn publish_ingestion_catalog_after_trees<'a>(
+    trees: impl IntoIterator<Item = &'a Path>,
+    catalog: &Path,
+    bytes: &[u8],
+) -> io::Result<()> {
+    let mut group = SyncGroup::default();
+    for tree in trees {
+        flush_tree(tree, &mut group)?;
+        group.flush_directory(parent(tree))?;
+    }
+    let replacement = Replacement::prepare(catalog, |writer| writer.write_all(bytes))?;
+    group.include_flushed(replacement.writer.get_ref().try_clone()?, catalog)?;
+    group.flush_directory(parent(catalog))?;
+    group.finish()?;
+    checkpoint("ingestion_data_durable", catalog)?;
+    replacement.publish()?;
+    checkpoint("flush_ingestion_catalog_directory", parent(catalog))?;
+    flush_file(&File::open(parent(catalog))?)
+}
